/*
 * ssl_sock_ctx flags
 */
#define SSL_SOCK_F_EARLY_ENABLED	(1 << 0) /* We did not start the handshake yet so we can send early data */
#define SSL_SOCK_F_KTLS_ENABLED         (1 << 1) /* We can use KTLS on that socket */
#define SSL_SOCK_F_KTLS_SEND            (1 << 2) /* kTLS send is configured on that socket */
#define SSL_SOCK_F_KTLS_RECV            (1 << 3) /* kTLS receive is configure on that socket */
#define SSL_SOCK_F_CTRL_SEND            (1 << 4) /* We want to send a kTLS control message for that socket */
#define SSL_SOCK_F_HAS_ALPN             (1 << 5) /* An ALPN has been negotiated */
#define SSL_SOCK_F_KTLS_ULP             (1 << 6) /* TLS ULP is enabled on that socket */

struct ssl_sock_ctx {
	struct connection *conn;
	SSL *ssl;
	BIO *bio;
	const struct xprt_ops *xprt;
	void *xprt_ctx;
	struct wait_event wait_event;
	struct wait_event *subs;
	int xprt_st;                  /* transport layer state, initialized to zero */
	unsigned long error_code;     /* last error code of the error stack */
	struct buffer early_buf;      /* buffer to store the early data received */
	int sent_early_data;          /* Amount of early data we sent so far */
	int flags;                    /* Various flags for the ssl_sock_ctx */
#ifdef HA_USE_KTLS
	char record_type;             /* Record type to use if not just sending application data */
#endif

#ifdef USE_QUIC
	struct quic_conn *qc;
#endif
};

struct global_ssl {
	char *crt_base;             /* base directory path for certificates */
	char *key_base;             /* base directory path for private keys */
	char *ca_base;              /* base directory path for CAs and CRLs */
	char *issuers_chain_path;   /* from "issuers-chain-path" */
	int  skip_self_issued_ca;

	int  async;                 /* whether we use ssl async mode */

	char *listen_default_ciphers;

	if (detect_shutr && ctx->conn->flags & (CO_FL_ERROR | CO_FL_SOCK_RD_SH)) {
		ret = -1;
	}
	BIO_clear_retry_flags(h);
	if (ret == 0 && !(ctx->conn->flags & (CO_FL_ERROR | CO_FL_SOCK_RD_SH))) {
		BIO_set_retry_read(h);
		ret = -1;
	}
#ifdef HA_USE_KTLS
#ifdef HAVE_VANILLA_OPENSSL
	if (ret > 0 && msg_controllen > 0) {
		cmsg = (void *)&cmsgbuf;

		if (cmsg->cmsg_type == TLS_GET_RECORD_TYPE) {
			/*
			 * The kernel strips the TLS record header, but openssl
			 * expects them back, so bring them back.
			 */
			buf[0] = *((unsigned char *)CMSG_DATA(cmsg));
			buf[1] = TLS_1_2_VERSION_MAJOR;
			buf[2] = TLS_1_2_VERSION_MINOR;
			buf[3] = (ret >> 8) & 0xff;
			buf[4] = ret & 0xff;
			ret += SSL3_RT_HEADER_LENGTH;
		}
	}
#endif
#endif
	return ret;
}

#ifdef HA_USE_KTLS
static int ktls_enable_ulp(struct ssl_sock_ctx *ctx)
{
	int ret = 0;

	if (!(ctx->flags & SSL_SOCK_F_KTLS_ULP)) {
		ret = setsockopt(ctx->conn->handle.fd, SOL_TCP, TCP_ULP, "tls",
				 sizeof("tls"));
		if (ret == 0)
			ctx->flags |= SSL_SOCK_F_KTLS_ULP;
		else
			ctx->flags &= ~SSL_SOCK_F_KTLS_ENABLED;
	}

	return ret;
}

/* Returns 0 on success, -1 on failure */
static int ktls_set_key(struct ssl_sock_ctx *ctx, void *info, size_t info_len, int is_tx)
{
	int opt_to_use = is_tx ? TLS_TX : TLS_RX;

	return setsockopt(ctx->conn->handle.fd, SOL_TLS, opt_to_use, info, info_len);
}
